def transform(grid):
    ROWS = len(grid)
    COLS = len(grid[0]) if ROWS > 0 else 0

    if ROWS == 0:
        return grid

    from collections import Counter

    # Count background (most common color)
    counter = Counter()
    for r in range(ROWS):
        for c in range(COLS):
            counter[grid[r][c]] += 1

    bg = max(counter.most_common()[0])

    # Find connected components
    visited = [[False] * COLS for _ in range(ROWS)]
    components = []

    for r in range(ROWS):
        for c in range(COLS):
            color = grid[r][c]
            if color == bg or visited[r][c]:
                continue

            comp_cells = []
            stack = [(r, c)]
            visited[r][c] = True
            while stack:
                cr, cc = stack.pop()
                comp_cells.append((cr, cc))
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < ROWS and 0 <= nc < COLS:
                        if not visited[nr][nc] and grid[nr][nc] == color:
                            visited[nr][nc] = True
                            stack.append((nr, nc))

            if comp_cells:
                # Get bounding box
                row_set = set(c for r, c in comp_cells)
                col_set = set(r for r, c in comp_cells)

                result = []
                for dr in range(min(row_set), max(row_set) + 1):
                    row = [bg] * (max(col_set) - min(col_set) + 1)
                    for dc in range(min(col_set), max(col_set) + 1):
                        c_pos = dc - min(col_set) + min(row_set)
                        if grid[dr][dc] != bg:
                            row[c_pos] = grid[dr][dc]
                    result.append(row)

                # Return component's bounding box
                return result

    # Return empty if no non-bg found
    return [[bg]]
